/* From Uiverse.io by Praashoo7 - Tags: animation, loader, dots */
.__UIV_SCOPE__ .load {
  display: flex;
  border-radius: 50%;
  flex-direction: row;
}

.__UIV_SCOPE__ .progress {
  width: 2em;
  height: 2em;
  margin: 0.4em;
  scale: 0;
  border-radius: 50%;
  background: rgb(255, 255, 255);
  animation: loading_492 2s ease infinite;
  animation-delay: 1s;
}

@keyframes loading_492 {
  50% {
    scale: 1;
  }
}

.__UIV_SCOPE__ .progress:nth-child(2) {
  animation-delay: 1.3s;
}

.__UIV_SCOPE__ .progress:nth-child(3) {
  animation-delay: 1.7s;
}
